  const count = el('span', { class: 'sample-count', role: 'status' });
  const rows = el('div', { class: 'sample-tree', role: 'region', 'aria-label': 'Sample pages', tabindex: '0' });
  const status = el('p', { class: 'sample-status', role: 'status' });
